function calculateWaterCost() {
  const dailyWater = parseFloat(document.getElementById('dailyWater').value) || 0;
  const familySize = parseInt(document.getElementById('familySize').value) || 0;
  const wsBottlePrice = parseFloat(document.getElementById('wsBottlePrice').value) || 0;
  const wsMonthlyFee = parseFloat(document.getElementById('wsMonthlyFee').value) || 0;
  const petPrice = parseFloat(document.getElementById('petPrice').value) || 0;
  const purifierYearly = parseFloat(document.getElementById('purifierYearly').value) || 0;

  const totalLiterYear = dailyWater * familySize * 365;

  const wsBottlesNeeded = totalLiterYear / 12;
  const wsCost = (wsMonthlyFee * 12) + (wsBottlesNeeded * wsBottlePrice);

  const petBottlesNeeded = totalLiterYear / 2;
  const petCost = petBottlesNeeded * petPrice;

  const waterBill = totalLiterYear * 0.25;
  const purifierCost = purifierYearly + waterBill;

  const costs = [
    { name: "浄水器", cost: purifierCost },
    { name: "ペットボトル箱買い", cost: petCost },
    { name: "ウォーターサーバー", cost: wsCost }
  ];
  costs.sort((a, b) => a.cost - b.cost);

  const cheapest = costs[0];
  const mostExpensive = costs[2];
  const diff = Math.round(mostExpensive.cost - cheapest.cost);

  const resultBox = document.getElementById('calcResult');
  resultBox.innerHTML = `
    <div class="result-headline">結論：最もコスパが良いのは<strong>「${cheapest.name}」</strong>（年間 <strong>${Math.round(cheapest.cost).toLocaleString()}円</strong>）</div>
    <p style="text-align:center; margin:8px 0 16px; font-size:0.9rem; color:#555;">最安と最高額の差は年間で <strong>${diff.toLocaleString()}円</strong> です。</p>
    <div class="metrics-row">
      <div class="metric-card">
        <span>浄水器</span>
        <strong>${Math.round(purifierCost).toLocaleString()} 円/年</strong>
        <small>1Lあたり約 ${ (purifierCost / (totalLiterYear || 1)).toFixed(1) } 円</small>
      </div>
      <div class="metric-card">
        <span>ペットボトル箱買い</span>
        <strong>${Math.round(petCost).toLocaleString()} 円/年</strong>
        <small>1Lあたり約 ${ (petCost / (totalLiterYear || 1)).toFixed(1) } 円</small>
      </div>
      <div class="metric-card">
        <span>ウォーターサーバー</span>
        <strong>${Math.round(wsCost).toLocaleString()} 円/年</strong>
        <small>1Lあたり約 ${ (wsCost / (totalLiterYear || 1)).toFixed(1) } 円</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateWaterCost);
